// src/validation.ts
function validateSourceTree(root, manifest2, ctx) {
  const plan = planPack(root, manifest2);
  const files = readFiles(plan);
  const report = ctx.validators.validateSource(files);
  const scan = ctx.validators.scanProject(files, { phase: "source" });
  const findings = [...report.findings, ...scan];
  const ok = report.ok && report.issues.every((i2) => i2.severity !== "error") && !hasBlock(findings);
  return { ok, issues: report.issues, findings, plan, fileCount: plan.files.length };
}
function printSourceCheck(c, ctx) {
  for (const i2 of c.issues)
    ctx.out.log(formatIssue(i2));
  for (const f of c.findings)
    for (const l of formatFinding(f))
      ctx.out.log(l);
}

