import { readFileSync as readFileSync4 } from "fs";
import { join as join6 } from "path";
var checkFlags = {
  players: { type: "number", alias: "p", default: 1, description: "simulated players for the headless match (2+ plays a multiplayer match through the SDK)" },
  seed: { type: "number", default: 1, description: "seed of the monkey (same seed, same inputs)" },
  seconds: { type: "number", default: 8, description: "monkey time per pass" },
  browser: { type: "boolean", default: true, description: "run the headless browser passes (--no-browser to stop after the static checks)" }
};
async function runCheck(a, ctx) {
  const players = a.flags.players;
  if (!Number.isInteger(players) || players < 1 || players > 8)
    throw new UsageError("--players must be a whole number from 1 to 8");
  const p = loadProject(a.positionals[0] ?? ctx.cwd);
  let failed = false;
  const step = (s) => ctx.out.log(`
== ${s}`);
  step("1. manifest and source (same validators as the server)");
  for (const w of p.warnings)
    ctx.out.log(`  [warning] ${w.path || "(root)"}: ${w.message} (${w.code})`);
  for (const l of await sdkAdvisories(p.root, ctx))
    ctx.out.log(l);
  const src = validateSourceTree(p.root, p.manifest, ctx);
  printSourceCheck(src, ctx);
  ctx.out.log(src.ok ? `  ok (${src.fileCount} files)` : "  FAILED");
  failed ||= !src.ok;
  step(`2. build (${p.manifest.build.template} template)`);
  let built = false;
  const depProblems = dependencySourceProblems(p.root, sdkBase(ctx));
  if (depProblems.length) {
    for (const m of depProblems)
      ctx.out.log(`  [error] ${sanitize(m, 400)}`);
    failed = true;
  } else if (src.ok || p.manifest.build.template === "static") {
    const b = await buildProject(p.root, p.manifest, { runner: ctx.runner, env: ctx.env, log: (s) => ctx.out.log(`  ${s}`) });
    if (!b.ok) {
      for (const i2 of b.issues)
        ctx.out.log(`  [error] ${sanitize(i2, 200)}`);
      for (const l of sanitize(b.log, 1e4).split(`
`).slice(-30))
        ctx.out.log(`    ${l}`);
      failed = true;
    } else {
      ctx.out.log(`  ok -> ${b.outDir}`);
      built = true;
    }
  } else
    ctx.out.log("  skipped (fix the source problems first)");
  step("3. rules scan of the output");
  if (built) {
    const out = outputFiles(p.root, p.manifest);
    const map2 = new Map(out.map((f) => [f.path, new Uint8Array(readFileSync4(f.abs))]));
    const findings = ctx.validators.scanProject(map2, { phase: "output" });
    for (const f of findings)
      for (const l of formatFinding(f))
        ctx.out.log(l);
    ctx.out.log(hasBlock(findings) ? "  FAILED" : `  ok (${out.length} files)`);
    failed ||= hasBlock(findings);
  } else
    ctx.out.log("  skipped");
  if (!a.flags.browser)
    ctx.out.log(`
(headless run skipped: --no-browser)`);
  else if (!built)
    ctx.out.log(`
(headless run skipped: nothing to run yet)`);
  else {
    step(`4. headless run in osg dev (${players} player${players > 1 ? "s" : ""}, seed ${a.flags.seed})`);
    const r2 = await runHeadless({
      root: p.root,
      manifest: p.manifest,
      players,
      seed: a.flags.seed,
      monkeyMs: Math.max(1, a.flags.seconds) * 1000,
      driver: ctx.browser,
      startDev: ctx.startDev,
      env: ctx.env,
      shotsDir: join6(p.root, ".osg", "check"),
      note: (s) => ctx.out.log(`  ${s}`)
    });
    for (const i2 of r2.issues)
      ctx.out.log(`  [${i2.severity}] ${i2.id}: ${sanitize(i2.message, 400)}`);
    for (const s of r2.screenshots)
      ctx.out.log(`  screenshot ${s}`);
    ctx.out.log(r2.ok ? "  ok" : "  FAILED");
    failed ||= !r2.ok;
  }
  ctx.out.log(failed ? `
osg check: FAILED. Fix the items above, then run it again.` : `
osg check: all passed. The server repeats these checks (and a cloud-browser run) when you submit.`);
  return failed ? 1 : 0;
}

