    genre: m.genres?.[0] ?? "Other",
    features: catalogueFeatures(m),
    players: m.players,
    controls: m.input.controls,
    coverUrl: null,
    screenshots: [],
    author: { name: "you (osg dev)" },
    plays30d: s.db.playCount(s.project.gameId),
