  const stored = { v: 1, kLaunch: randomHex(32), kPlayer: randomHex(32), kRun: randomHex(32), kAnalytics: randomHex(32), kid: "dev1", ticketPrivB64: std64(priv), ticketPubB64: std64(pub) };
  writePrivateFile(file2, JSON.stringify(stored, null, 2));
