// ../dev/src/emulator-page.ts
import { dirname as dirname6, join as join10 } from "path";

// ../dev/src/emulator/fonts.ts
var FONT_CSS = '@font-face{font-family:"Geist";font-style:normal;font-weight:100 900;font-display:swap;src:url(data:font/woff2;base64,) format("woff2")}@font-face{font-family:"Geist Mono";font-style:normal;font-weight:100 900;font-display:swap;src:url(data:font/woff2;base64,) format("woff2")}@font-face{font-family:"Bricolage Grotesque";font-style:normal;font-weight:200 800;font-display:swap;src:url(data:font/woff2;base64,) format("woff2")}@font-face{font-family:"Protest Strike";font-style:normal;font-weight:400;font-display:swap;src:url(data:font/woff2;base64,) format("woff2")}';

// ../dev/src/emulator/style.ts
var CSS = FONT_CSS + `
:root{--bg:#05060a;--ink:#f2f4f8;--muted:#a3abbd;--dim:#8b93a6;--cyan:#4ff3ff;--live:#9dffb6;--warn:#ffb020;--bad:#ff6b5e;
--line:rgba(255,255,255,.14);--glass:rgba(255,255,255,.07);--panel:rgba(18,20,30,.82);
--ui:"Geist",system-ui,-apple-system,"Segoe UI",sans-serif;--mono:"Geist Mono",ui-monospace,Menlo,monospace;
--display:"Bricolage Grotesque","Arial Narrow",system-ui,sans-serif;--logo:"Protest Strike","Arial Narrow",Impact,sans-serif;color-scheme:dark}
*{box-sizing:border-box}
html,body{height:100%;margin:0}
body{background:radial-gradient(120% 70% at 50% -10%,#0c1424 0%,var(--bg) 62%) fixed,var(--bg);color:var(--ink);font:15px/1.5 var(--ui);overflow:hidden}
button,select,input{font:inherit;color:inherit}
button{cursor:pointer}
:focus-visible{outline:2px solid var(--cyan);outline-offset:2px}
button:disabled{opacity:.5;cursor:default}
#app{height:100%}
.floor{position:fixed;inset:auto 0 0 0;height:55%;perspective:560px;overflow:hidden;z-index:-1;pointer-events:none;-webkit-mask-image:linear-gradient(to top,#000 10%,transparent);mask-image:linear-gradient(to top,#000 10%,transparent)}
.floor::before{content:"";position:absolute;inset:-60% -60% 0;transform:rotateX(64deg);transform-origin:50% 100%;background-image:linear-gradient(rgba(79,243,255,.2) 1px,transparent 1px),linear-gradient(90deg,rgba(79,243,255,.2) 1px,transparent 1px);background-size:64px 64px}

/* top bar */
.shell{display:grid;grid-template-rows:auto minmax(0,1fr);height:100%}
.topbar{display:flex;align-items:center;gap:12px 18px;flex-wrap:wrap;padding:14px 20px}
.lockup{display:grid;justify-items:start;gap:4px;line-height:1;flex:none}
.lockup small{font:500 8px/1 var(--mono);letter-spacing:.5em;color:var(--muted);text-transform:uppercase}
.lockup b{font:400 19px/.86 var(--logo);text-transform:uppercase;letter-spacing:.01em}
.title{font:700 18px/1.1 var(--display);letter-spacing:-.01em;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.mode{display:inline-flex;align-items:center;gap:8px;padding:6px 12px;border-radius:999px;background:var(--glass);border:1px solid var(--line);font-size:13px;color:var(--muted);margin-left:auto;white-space:nowrap}
.mode i{width:8px;height:8px;border-radius:50%;background:var(--live);box-shadow:0 0 10px rgba(157,255,182,.7)}
.mode.warn{margin-left:0;color:var(--warn);border-color:rgba(255,176,32,.4)}

/* the game */
.stagewrap{min-height:0;display:grid;place-items:center;padding:0 24px 104px}
.frame{position:relative;width:100%;height:100%;transition:width .2s,height .2s}
#stage{position:absolute;inset:0;background:#000;border:1px solid var(--line);border-radius:18px;overflow:hidden;box-shadow:0 30px 80px rgba(0,0,0,.55)}
#stage iframe{position:absolute;inset:0;width:100%;height:100%;border:0;background:#000}
body.phone .frame{width:min(390px,100%);height:min(780px,100%)}
body.phone #stage{border-radius:28px;border-width:6px;border-color:#1b1e2a}

/* buttons */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:42px;padding:0 16px;border-radius:999px;border:1px solid transparent;font-weight:600;font-size:14px;white-space:nowrap;transition:transform .15s,background .15s,color .15s,border-color .15s;background:none}
.btn:hover:not(:disabled){transform:translateY(-1px)}
.btn.primary{background:var(--ink);color:#05060a}
.btn.glass{background:var(--glass);border-color:var(--line);backdrop-filter:blur(16px)}
.btn.glass:hover{background:rgba(255,255,255,.12)}
.btn.quiet{color:var(--muted)}
.btn.quiet:hover{color:var(--ink);border-color:var(--line)}
.btn.small{min-height:34px;font-size:13px;padding:0 12px}
.btn.icon{width:38px;min-height:38px;padding:0}
.btn.danger{color:var(--bad)}
.btn svg{width:16px;height:16px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round;flex:none}
.btn svg circle{fill:currentColor;stroke:none}

/* the dock */
.controls{position:fixed;left:50%;bottom:22px;transform:translateX(-50%);z-index:40;display:flex;align-items:center;gap:6px;padding:8px;border-radius:999px;background:var(--panel);border:1px solid var(--line);backdrop-filter:blur(24px) saturate(160%);-webkit-backdrop-filter:blur(24px) saturate(160%);box-shadow:0 20px 50px rgba(0,0,0,.5);max-width:calc(100% - 24px)}
@media (min-width:1100px){body.drawer-open .controls{left:calc(50% - 190px)}}
.controls{transition:left .22s}
.controls .sep{width:1px;height:24px;background:var(--line);margin:0 4px;flex:none}
.who{display:flex;align-items:center;gap:10px;padding:0 8px 0 4px;min-width:0}
.who>div{display:grid;line-height:1.25;min-width:0}
.who .name{font-weight:600;font-size:14px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:14ch}
.who small{color:var(--muted);font-size:12px;white-space:nowrap}
.av{position:relative;display:inline-grid;place-items:center;width:30px;height:30px;border-radius:50%;color:#05060a;font:700 13px var(--ui);flex:none;overflow:hidden}
.av img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}

/* the More drawer */
.drawer{position:fixed;top:0;right:0;bottom:0;width:min(380px,100%);z-index:60;background:var(--panel);border-left:1px solid var(--line);backdrop-filter:blur(30px) saturate(160%);-webkit-backdrop-filter:blur(30px) saturate(160%);padding:20px;display:grid;gap:22px;align-content:start;overflow-y:auto;box-shadow:-20px 0 60px rgba(0,0,0,.4)}
.drawer[hidden]{display:none}
.drawer header{display:flex;justify-content:space-between;align-items:center}
.drawer header b{font:700 20px/1 var(--display);letter-spacing:-.01em}
.sect{display:grid;gap:10px}
.sect[hidden]{display:none}
.sect h3{margin:0;font:500 10px/1 var(--mono);letter-spacing:.22em;text-transform:uppercase;color:var(--dim)}
.facts{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:1fr 1fr;gap:8px}
.facts li{padding:10px 12px;border-radius:14px;background:var(--glass);border:1px solid var(--line);display:grid;gap:2px;min-width:0}
.facts b{font:700 20px/1.1 var(--display);font-variant-numeric:tabular-nums;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.facts span{color:var(--muted);font-size:12px}
.fine{margin:0;color:var(--muted);font-size:13px}
.fine.link{word-break:break-all}
.people{list-style:none;margin:0;padding:0;display:grid;gap:6px}
.people li{display:flex;justify-content:space-between;gap:10px;padding:8px 12px;border-radius:12px;background:var(--glass);border:1px solid var(--line);font-size:14px}
.people small{color:var(--muted);font-size:12px}
.code{font:700 18px/1 var(--display);letter-spacing:.08em}
.row{display:flex;align-items:center;gap:8px;flex-wrap:wrap}
.toggle{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:10px 12px;border-radius:14px;background:var(--glass);border:1px solid var(--line);font-size:14px}
.toggle small{display:block;color:var(--muted);font-size:12px}
.toggle small:empty{display:none}
.toggle.inline{background:none;border:0;padding:0}
.sw{position:relative;width:40px;height:24px;border-radius:999px;background:rgba(255,255,255,.14);border:0;flex:none;transition:background .15s;padding:0}
.sw::after{content:"";position:absolute;top:3px;left:3px;width:18px;height:18px;border-radius:50%;background:var(--ink);transition:transform .15s}
.sw[aria-checked="true"]{background:var(--cyan)}
.sw[aria-checked="true"]::after{transform:translateX(16px);background:#05060a}
details.dev{border-radius:14px;border:1px solid var(--line);background:rgba(255,255,255,.03)}
details.dev summary{list-style:none;cursor:pointer;padding:12px 14px;display:flex;justify-content:space-between;align-items:center;color:var(--muted);font-size:14px;border-radius:14px}
details.dev summary::-webkit-details-marker{display:none}
details.dev summary::after{content:"\\203A";font-size:18px;transition:transform .15s}
details.dev[open] summary::after{transform:rotate(90deg)}
details.dev .in{padding:0 14px 14px;display:grid;gap:14px}
.group{display:grid;gap:8px}
details.dev h4{margin:0;font-size:12px;font-weight:600;color:var(--dim)}
.devbtns{display:flex;flex-wrap:wrap;gap:6px}
.log{font:500 11px/1.6 var(--mono);color:var(--dim);background:rgba(0,0,0,.35);border-radius:10px;padding:8px 10px;max-height:180px;overflow:auto;white-space:pre-wrap;word-break:break-word}
.log .err{color:var(--bad)}.log .ui{color:var(--ink)}

/* toasts, banner, killed screen */
.toasts{position:fixed;top:72px;left:50%;transform:translateX(-50%);display:flex;flex-direction:column;align-items:center;gap:8px;z-index:70;pointer-events:none;width:min(92vw,440px)}
.toast{display:grid;justify-items:center;text-align:center;padding:10px 18px;border-radius:22px;background:var(--ink);color:#05060a;box-shadow:0 12px 30px rgba(0,0,0,.5);pointer-events:auto;font-size:14px}
.toast b{font-weight:600}
.toast span{font-size:13px;color:#3a4152}
.toast.error{background:#2a1214;color:var(--ink);border:1px solid rgba(255,107,94,.5)}
.toast.error span{color:#f3c2bd}
.toast.achievement b::before{content:"\\2605 ";color:#d08a00}
.banner{position:absolute;left:50%;top:12px;transform:translateX(-50%);z-index:5;padding:6px 14px;border-radius:999px;background:var(--warn);color:#201400;font-weight:600;font-size:13px;white-space:nowrap}
.banner.offline{background:var(--bad);color:#1a0503}
.killed{position:absolute;inset:0;z-index:9;background:var(--bg);display:flex;flex-direction:column;gap:12px;align-items:center;justify-content:center;text-align:center;padding:24px}
.killed h2{margin:0;font:800 26px/1.1 var(--display);letter-spacing:-.02em}
.killed p{margin:0;color:var(--muted);max-width:42ch}

/* the product's floating game widget, in a corner of the game */
.widget{position:absolute;bottom:14px;z-index:20}
.widget.right{right:14px}.widget.left{left:14px}
.widget>button.pill{border-radius:999px;padding:8px 14px;background:var(--panel);border:1px solid var(--line);backdrop-filter:blur(16px);box-shadow:0 4px 18px rgba(0,0,0,.35);font-size:13px;font-weight:600}
.widget .menu{position:absolute;bottom:44px;min-width:200px;background:var(--panel);backdrop-filter:blur(24px);border:1px solid var(--line);border-radius:16px;padding:6px;display:flex;flex-direction:column;gap:2px;box-shadow:0 8px 28px rgba(0,0,0,.45)}
.widget.right .menu{right:0}.widget.left .menu{left:0}
.widget .menu[hidden]{display:none}
.widget .menu button{text-align:left;border:0;background:transparent;padding:8px 10px;border-radius:10px;font-size:14px}
.widget .menu button:hover,.widget .menu button:focus-visible{background:var(--glass)}

/* room chat */
.dock{position:fixed;z-index:30;width:min(92vw,320px);background:var(--panel);backdrop-filter:blur(24px);border:1px solid var(--line);border-radius:18px;box-shadow:0 8px 28px rgba(0,0,0,.45);display:flex;flex-direction:column;max-height:45vh}
.dock[hidden]{display:none}
.dock.bottom-left{left:16px;bottom:96px}.dock.bottom-right{right:16px;bottom:96px}.dock.top-left{left:16px;top:72px}.dock.top-right{right:16px;top:72px}
.dock .msgs{overflow:auto;padding:10px;display:flex;flex-direction:column;gap:4px;min-height:60px}
.dock .msg{font-size:13px}.dock .msg .who{display:inline;padding:0;color:var(--cyan);font-weight:600}.dock .msg.mine .who{color:var(--live)}
.dock .msg button{padding:0 6px;font-size:11px;margin-left:4px;background:none;border:1px solid var(--line);border-radius:999px;color:var(--muted)}
.dock .send{display:flex;flex-wrap:wrap;gap:4px;padding:8px;border-top:1px solid var(--line)}
.dock .send input{flex:1;min-width:120px;background:var(--glass);border:1px solid var(--line);border-radius:999px;padding:6px 12px}
.dock .send button{background:var(--glass);border:1px solid var(--line);border-radius:999px;padding:4px 10px;font-size:13px}
.dock .emotes img{width:22px;height:22px;vertical-align:middle}

/* dialogs */
dialog{background:rgba(18,20,30,.94);color:var(--ink);border:1px solid var(--line);border-radius:22px;padding:22px;max-width:min(92vw,460px);box-shadow:0 30px 80px rgba(0,0,0,.6)}
dialog::backdrop{background:rgba(5,6,10,.7);backdrop-filter:blur(4px)}
dialog h2{margin:0 0 10px;font:700 22px/1.15 var(--display);letter-spacing:-.01em}
dialog p{margin:0 0 10px}
dialog .actions{display:flex;gap:8px;justify-content:flex-end;margin-top:16px;flex-wrap:wrap}
.party{font:800 32px/1 var(--display);letter-spacing:.08em}
table.board{width:100%;border-collapse:collapse;margin-bottom:10px}
table.board td,table.board th{padding:6px 8px;border-bottom:1px solid var(--line);text-align:left}
table.board th{font:500 10px/1 var(--mono);letter-spacing:.18em;text-transform:uppercase;color:var(--dim)}
table.board tr.you{background:var(--glass);font-weight:600}
table.board img{width:20px;height:20px;vertical-align:middle;margin-right:8px;border-radius:50%}

/* simulated peers play off screen */
.peers{position:fixed;left:-10000px;top:0;width:640px;height:360px;overflow:hidden;visibility:visible}
.peers .peer{position:relative;width:640px;height:360px}
.peers iframe{width:100%;height:100%;border:0}

@media (max-width:820px){
  .mode-more{display:none}
  .controls .label{display:none}
  .controls .btn{width:42px;padding:0}
  .who .name{max-width:9ch}
  .stagewrap{padding:0 12px 92px}
  .topbar{padding:12px 16px}
}
@media (max-width:420px){.who>div{display:none}.lockup{display:none}}
@media (prefers-reduced-motion:no-preference){
  .toast{animation:in .18s ease-out}@keyframes in{from{opacity:0;transform:translateY(-6px)}to{opacity:1;transform:none}}
  .drawer:not([hidden]){animation:slide .22s ease-out}@keyframes slide{from{transform:translateX(24px);opacity:0}to{transform:none;opacity:1}}
}
@media (prefers-reduced-motion:reduce){*{transition:none!important;animation:none!important}}
`;

