// ../dev/src/events.ts
import { appendFileSync, mkdirSync as mkdirSync7 } from "fs";
import { dirname as dirname7 } from "path";
var HOUR = 3600000;
function createLocalEvents(file2) {
  const all = [];
  let dirReady = false;
  return {
    emit(e) {
      all.push(e);
      if (all.length > 5000)
        all.splice(0, all.length - 5000);
      if (!file2)
        return;
      try {
        if (!dirReady) {
          mkdirSync7(dirname7(file2), { recursive: true });
          dirReady = true;
        }
        appendFileSync(file2, JSON.stringify(e) + `
`);
      } catch {}
    },
    recent(n = 50) {
      return all.slice(-n);
    },
    async hourlyTotals({ fromHour, toHour }) {
      const rows = new Map;
      for (const e of all) {
        const hour = Math.floor(e.at / HOUR);
        if (hour < fromHour || hour > toHour)
          continue;
        const k = `${e.game}:${hour}`;
        let r2 = rows.get(k);
        if (!r2) {
          r2 = { game_id: e.game, hour, plays: 0, scored_submits: 0, uniq_players: 0, guests: 0, play_seconds: 0, errors: 0, sampled: 0, players: new Set };
          rows.set(k, r2);
        }
        if (e.kind === "play_start")
          r2.plays++;
        if (e.kind === "score")
          r2.scored_submits++;
        if (e.kind === "play_end")
          r2.play_seconds += Math.round((e.durationMs ?? 0) / 1000);
        if (!r2.players.has(e.playerHash)) {
          r2.players.add(e.playerHash);
          r2.uniq_players++;
          if (e.playerKind === "guest")
            r2.guests++;
        }
      }
      return [...rows.values()].map(({ players: _p, ...row }) => row);
    }
  };
}

