  const c = validateSourceTree(p.root, p.manifest, ctx);
  printSourceCheck(c, ctx);
  ctx.out.log(c.ok ? `OK: ${p.manifest.slug} passes source validation (${c.fileCount} files).` : `FAILED: ${p.manifest.slug} has problems above. The server runs the same checks.`);
